// Hand-written (not generated by buf): the message size limits both ends
// of the worker contract configure explicitly, instead of gRPC's 4 MiB
// receive default — under which a realistic inventory snapshot could never
// be claimed (final review I3). The manager's gRPC server and the worker's
// client read the same constants, so the two ends cannot drift.

package workerpb

// Message size limits of the WorkerService contract.
const (
	// MaxManagerToWorkerBytes bounds what the manager sends a worker: the
	// claim response, which embeds the rendered inventory snapshot, the
	// connections and the revealed credentials. 64 MiB fits inventories of
	// tens of thousands of hosts with generous per-host variables.
	MaxManagerToWorkerBytes = 64 << 20
	// MaxWorkerToManagerBytes bounds what a worker sends the manager: one
	// run event (its payload truncated to MaxEventPayloadBytes by the
	// worker), a claim request, or the terminal result with its per-host
	// stats lists.
	MaxWorkerToManagerBytes = 16 << 20
	// MaxEventPayloadBytes is the per-event payload bound the worker
	// enforces before sending: a larger payload (a verbose module result,
	// a huge stdout line) is replaced by a truncation marker carrying the
	// payload's head, so the event itself is never lost.
	MaxEventPayloadBytes = 1 << 20
)
